import React, { useEffect, useState } from 'react';

import type { RicosEditorProps } from './../../ricos-common/index.js';
import type { TFunction } from './../../ricos-types/index.js';
import { RicosTranslate, fetchEditorTranslations } from './../../wix-rich-content-common/index.js';

type LocaleResourceProviderProps = {
  locale: string | undefined;
  children: (locale: RicosEditorProps['locale']) => (t: TFunction) => React.ReactNode;
  fallback: React.ReactNode;
};

export function LocaleResourceProvider({
  locale,
  children,
  fallback,
}: LocaleResourceProviderProps): any {
  const [currentLocaleResource, setLocaleResource] = useState<{
    locale: string;
    localeResource?: Record<string, string>;
  } | null>(null);

  // custom hook
  useEffect(() => {
    const handleLocaleResource = async () => {
      const localeResource = await fetchEditorTranslations(locale);
      if (localeResource) {
        setLocaleResource(localeResource);
      }
    };

    handleLocaleResource();
  }, []);

  if (!currentLocaleResource) {
    return fallback;
  }
  return (
    <RicosTranslate
      locale={currentLocaleResource.locale}
      localeResource={currentLocaleResource.localeResource ?? {}}
    >
      {children(currentLocaleResource.locale)}
    </RicosTranslate>
  );
}

// oxlint-disable-next-line import/no-default-export
export default LocaleResourceProvider;
